WITH base AS (
 SELECT order_id,COUNT(*) AS n FROM commerce.orders
 WHERE order_purchase_timestamp >= DATE '2018-07-01' AND order_purchase_timestamp < DATE '2018-08-01' GROUP BY order_id
 ), events AS (
 SELECT r.* FROM cx.returns r JOIN base b ON r.order_id=b.order_id
 ), r AS (
 SELECT order_id,COUNT(*) AS events,SUM(refund_amount::numeric) AS amount FROM events GROUP BY order_id
 ), joined AS (SELECT b.order_id,b.n,COALESCE(r.events,0) AS events,COALESCE(r.amount,0) AS amount FROM base b LEFT JOIN r ON b.order_id=r.order_id) SELECT COUNT(*) AS orders,COUNT(*) FILTER(WHERE events>0) AS returned_orders,COUNT(*) FILTER(WHERE amount>0) AS refunded_orders,COALESCE(SUM(events),0) AS events,COALESCE(SUM(amount),0)::text AS refund_amount,(SELECT COUNT(*) FROM base WHERE n<>1 OR order_id IS NULL OR BTRIM(order_id)='') AS invalid_orders,
 (SELECT COUNT(*) FROM events WHERE return_id IS NULL OR BTRIM(return_id)='' OR refund_amount IS NULL OR refund_amount::text IN ('NaN','Infinity','-Infinity') OR refund_amount<0) AS invalid_events,
 (SELECT COUNT(*)-COUNT(DISTINCT return_id) FROM events) AS duplicate_events,(SELECT COUNT(*) FROM cx.returns x WHERE x.order_id IS NULL OR NOT EXISTS(SELECT 1 FROM commerce.orders o WHERE o.order_id=x.order_id)) AS source_unlinked_events,(SELECT jsonb_agg(DISTINCT source_type) FROM events) AS source_types FROM joined

